fn less_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Ensure both vectors are of the same length
    assert_eq!(a.len(), b.len(), "Input arrays must have the same length");

    // Create a result vector of the same length
    let mut result = Vec::with_capacity(a.len());

    // Iterate through both vectors and compare elements
    for i in 0..a.len() {
        result.push(a[i] <= b[i]);
    }

    result
}